const state = { run: createExampleRun(), view: 'board', sort: 'signal', filter: 'all', loading: false, config: { liveAvailable: false }, saved: {}, notes: {}, selected: null, toastTimer: null, abort: null, failedRun: null, showFailedTrail: false };
